const query = String(tobub.params.searchKey || '').trim();
const count = Number(tobub.params.count ?? 10);
const maxPages = Number(tobub.params.maxPages ?? 4);
const sortBy = String(tobub.params.sortBy ?? 'relevance');
const initialWaitSeconds = Number(tobub.params.initialWaitSeconds ?? 5);
const pageWaitSeconds = Number(tobub.params.pageWaitSeconds ?? 2);
const saveResults = tobub.params.saveResults !== false;
if (!query || query.length > 120) throw new Error('searchKey must be from 1 to 120 characters.');
if (!Number.isInteger(count) || count < 1 || count > 50) throw new Error('count must be an integer from 1 to 50.');
if (!Number.isInteger(maxPages) || maxPages < 1 || maxPages > 8) throw new Error('maxPages must be an integer from 1 to 8.');
if (!['relevance', 'newest', 'mostLiked', 'mostViewed'].includes(sortBy)) throw new Error('Invalid sortBy value.');
if (!Number.isInteger(initialWaitSeconds) || initialWaitSeconds < 3 || initialWaitSeconds > 20) throw new Error('initialWaitSeconds must be from 3 to 20 seconds.');
if (!Number.isInteger(pageWaitSeconds) || pageWaitSeconds < 1 || pageWaitSeconds > 10) throw new Error('pageWaitSeconds must be from 1 to 10 seconds.');

const watch = await tobub.browser.network.watch({
  id: 'tiktok-search-results',
  urlPattern: { pattern: 'api/search/general/full' },
  resourceTypes: ['xhr', 'fetch'],
  captureResponseBody: true,
  maxBodyBytes: 2000000,
  maxRecords: Math.min(40, maxPages * 6)
});
await tobub.atoms.navigate({
  url: 'https://www.tiktok.com/search?q=' + encodeURIComponent(query),
  waitUntil: 'domcontentloaded'
});
await tobub.atoms.waitFor({ delay: initialWaitSeconds * 1000 });

const observed = new Map();
let pagesRead = 0;
let lastHasMore = null;
const readVisibleCards = async () => {
  const result = await tobub.atoms.evaluate({
    mode: 'expression',
    expression: '(()=>Array.from(document.querySelectorAll("a[href*=\\"/video/\\"]")).filter(a=>{const r=a.getBoundingClientRect();return r.width>0&&r.height>0}).map(a=>{const href=a.href.split("?")[0];const m=href.match(/\\/video\\/(\\d+)/);const authorMatch=href.match(/\\/@([^/]+)\\/video\\/(\\d+)/);const img=a.querySelector("img");return{videoId:m?m[1]:"",authorUsername:authorMatch?authorMatch[1]:"",videoUrl:href,description:String((img&&img.alt)||a.getAttribute("aria-label")||""),coverUrl:String((img&&(img.currentSrc||img.src))||"")}}).filter(x=>x.videoId))()'
  });
  const value = result && result.value !== undefined ? result.value : (result && result.result !== undefined ? result.result : result);
  return Array.isArray(value) ? value : [];
};
for (let page = 0; page < maxPages && observed.size < count; page++) {
  if (page > 0) {
    await tobub.atoms.scroll({ mode: 'viewport', direction: 'down', distance: 900, steps: 5, stepPauseRange: [35, 80] });
    await tobub.atoms.waitFor({ delay: pageWaitSeconds * 1000 });
  }
  for (const card of await readVisibleCards()) {
    if (card.videoId && !observed.has(card.videoId)) observed.set(card.videoId, { videoId: card.videoId, description: card.description || '', videoUrl: card.videoUrl, coverUrl: card.coverUrl || '', authorUsername: card.authorUsername || '', authorNickname: '', createTime: null, duration: null, playCount: null, likeCount: null, commentCount: null, shareCount: null, dataSource: 'search_result_dom' });
  }
}
const networkRecords = await tobub.browser.network.collect(watch, { stop: true });
const asCount = (value) => {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'object') value = value.value ?? value.count ?? value.displayText;
  const n = Number(String(value).replace(/,/g, '').trim());
  return Number.isFinite(n) && n >= 0 ? Math.trunc(n) : null;
};
const firstUrl = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && /^https?:\/\//i.test(value)) return value;
    if (value && typeof value === 'object') {
      for (const key of ['urlList', 'url_list', 'urls', 'url', 'src']) {
        const candidate = value[key];
        if (typeof candidate === 'string' && /^https?:\/\//i.test(candidate)) return candidate;
        if (Array.isArray(candidate)) {
          const found = candidate.find(item => typeof item === 'string' && /^https?:\/\//i.test(item));
          if (found) return found;
        }
      }
    }
  }
  return '';
};
for (const record of networkRecords) {
  const body = record?.response?.body;
  if (typeof body !== 'string' || record.response.bodyEncoding === 'base64') continue;
  if (record.response.status && (record.response.status < 200 || record.response.status >= 300)) continue;
  let requestUrl, payload;
  try { requestUrl = new URL(record.request.url); payload = JSON.parse(body); } catch { continue; }
  if (!requestUrl.pathname.includes('/api/search/general/full')) continue;
  pagesRead++;
  if (payload && typeof payload.has_more === 'number') lastHasMore = payload.has_more !== 0;
  else if (payload && typeof payload.has_more === 'boolean') lastHasMore = payload.has_more;
  const rows = Array.isArray(payload?.data) ? payload.data : [];
  for (const row of rows) {
    const item = row?.item && typeof row.item === 'object' ? row.item : row;
    if (!item || typeof item !== 'object') continue;
    const id = String(item.id ?? item.aweme_id ?? item.item_id ?? '');
    if (!/^\d{8,24}$/.test(id)) continue;
    const author = item.author && typeof item.author === 'object' ? item.author : {};
    const video = item.video && typeof item.video === 'object' ? item.video : {};
    const stats = item.stats && typeof item.stats === 'object' ? item.stats : (item.statsV2 || {});
    const username = String(author.uniqueId ?? author.unique_id ?? '');
    const normalized = {
      videoId: id,
      description: String(item.desc ?? item.description ?? ''),
      videoUrl: username ? 'https://www.tiktok.com/@' + encodeURIComponent(username) + '/video/' + id : 'https://www.tiktok.com/video/' + id,
      coverUrl: firstUrl(video.cover, video.originCover, video.dynamicCover, video.coverUrl),
      authorUsername: username,
      authorNickname: String(author.nickname ?? ''),
      createTime: asCount(item.createTime ?? item.create_time),
      duration: asCount(video.duration ?? item.duration),
      playCount: asCount(stats.playCount ?? stats.play_count ?? stats.viewCount),
      likeCount: asCount(stats.diggCount ?? stats.digg_count ?? stats.likeCount),
      commentCount: asCount(stats.commentCount ?? stats.comment_count),
      shareCount: asCount(stats.shareCount ?? stats.share_count),
      dataSource: 'api_search_general_full'
    };
    observed.set(id, normalized);
  }
}
const ordered = Array.from(observed.values());
const metricFor = (item) => sortBy === 'newest' ? item.createTime : (sortBy === 'mostLiked' ? item.likeCount : item.playCount);
if (sortBy !== 'relevance') ordered.sort((a, b) => {
  const av = metricFor(a), bv = metricFor(b);
  if (av === null || av === undefined) return bv === null || bv === undefined ? 0 : 1;
  if (bv === null || bv === undefined) return -1;
  return Number(bv) - Number(av);
});
const records = [];
for (const item of ordered.slice(0, count)) {
  let contentItemId = null;
  if (saveResults) {
    const saved = await tobub.db.saveContent({
      platform: 'tiktok',
      contentType: 'video',
      externalId: item.videoId,
      title: item.description || ('TikTok video ' + item.videoId),
      summary: item.authorNickname || (item.authorUsername ? '@' + item.authorUsername : ''),
      url: item.videoUrl,
      metadata: { ...item, query, sortBy },
      rawData: { ...item, query, sortBy }
    });
    if (!saved || !Number.isFinite(Number(saved.contentItemId))) throw new Error('Failed to save search results: ' + item.videoId);
    contentItemId = Number(saved.contentItemId);
  }
  records.push({ ...item, contentItemId });
}
const complete = records.length >= count || lastHasMore === false;
return {
  query,
  requestedCount: count,
  returnedCount: records.length,
  pagesRead,
  sortBy,
  saved: saveResults,
  complete,
  warning: records.length === 0 ? 'No search videos were extracted. TikTok may require login, show a verification challenge, or have no public results for this query. If prompted to log in, retry with a verified TikTok Profile.' : (complete ? '' : 'Available results were returned. Increase maxPages and retry to load more.'),
  records
};
